38	describe('#{#sdf1a}/#{#sdf5a} readDateFilter - read + validate from URL', () => {
39		it('reads both dateFrom and dateTo when present and valid', () => {
40			const params = new URLSearchParams('dateFrom=2025-01-01&dateTo=2025-01-31');
41			expect(readDateFilter(params)).toEqual({ dateFrom: '2025-01-01', dateTo: '2025-01-31' });
