47		});
48	
49		it('reads dateTo only, leaving dateFrom empty', () => {
50			const params = new URLSearchParams('dateTo=2025-01-31');
51			expect(readDateFilter(params)).toEqual({ dateFrom: '', dateTo: '2025-01-31' });
