91	describe('#{#sdf1b} matchesDateRange - client-side in-memory predicate', () => {
92		// This single predicate must reproduce the behaviour of all four pages. Three
93		// pages (expenses/receipts/reconciliation) guard a nullable date and KEEP rows
94		// with no date; transactions has a non-null date column, so the guarded and
95		// unguarded variants behave identically for it. The predicate below preserves
96		// both: a missing date is always kept.
97	
98		describe('rows with no date are always kept', () => {
99			it('keeps a null date even when both bounds are set', () => {
100				expect(matchesDateRange(null, '2025-01-01', '2025-01-31')).toBe(true);
101			});
102	
103			it('keeps an undefined date even when both bounds are set', () => {
104				expect(matchesDateRange(undefined, '2025-01-01', '2025-01-31')).toBe(true);
105			});
106	
107			it('keeps an empty-string date even when both bounds are set', () => {
108				expect(matchesDateRange('', '2025-01-01', '2025-01-31')).toBe(true);
109			});
110		});
111	
112		describe('no active filter', () => {
113			it('keeps any dated row when both bounds are empty', () => {
114				expect(matchesDateRange('2025-06-15', '', '')).toBe(true);
115			});
116	
117			it('keeps a null-dated row when both bounds are empty', () => {
118				expect(matchesDateRange(null, '', '')).toBe(true);
119			});
120		});
121	
122		describe('dateFrom only (lower bound, inclusive)', () => {
123			it('keeps a date after the lower bound', () => {
124				expect(matchesDateRange('2025-02-10', '2025-02-01', '')).toBe(true);
125			});
126	
127			it('keeps a date exactly on the lower bound', () => {
128				expect(matchesDateRange('2025-02-01', '2025-02-01', '')).toBe(true);
129			});
130	
131			it('excludes a date before the lower bound', () => {
132				expect(matchesDateRange('2025-01-31', '2025-02-01', '')).toBe(false);
