136		describe('dateTo only (upper bound, inclusive)', () => {
137			it('keeps a date before the upper bound', () => {
138				expect(matchesDateRange('2025-01-10', '', '2025-01-31')).toBe(true);
139			});
140	
141			it('keeps a date exactly on the upper bound', () => {
142				expect(matchesDateRange('2025-01-31', '', '2025-01-31')).toBe(true);
143			});
144	
145			it('excludes a date after the upper bound', () => {
146				expect(matchesDateRange('2025-02-01', '', '2025-01-31')).toBe(false);
147			});
148		});
149	
150		describe('full range (both bounds, inclusive)', () => {
151			it('keeps a date inside the range', () => {
152				expect(matchesDateRange('2025-01-15', '2025-01-01', '2025-01-31')).toBe(true);
153			});
154	
155			it('keeps a date on the lower boundary', () => {
156				expect(matchesDateRange('2025-01-01', '2025-01-01', '2025-01-31')).toBe(true);
157			});
158	
159			it('keeps a date on the upper boundary', () => {
160				expect(matchesDateRange('2025-01-31', '2025-01-01', '2025-01-31')).toBe(true);
161			});
162	
163			it('excludes a date below the range', () => {
164				expect(matchesDateRange('2024-12-31', '2025-01-01', '2025-01-31')).toBe(false);
165			});
166	
167			it('excludes a date above the range', () => {
168				expect(matchesDateRange('2025-02-01', '2025-01-01', '2025-01-31')).toBe(false);
169			});
170		});
171	
172		it('compares ISO strings lexicographically across year boundaries', () => {
173			// Guards against a regression to Date-based parsing (banned by CLAUDE.md for
174			// date-only strings): plain YYYY-MM-DD string comparison must order correctly.
175			expect(matchesDateRange('2024-12-31', '2025-01-01', '')).toBe(false);
176			expect(matchesDateRange('2025-01-01', '2025-01-01', '')).toBe(true);
