269	describe('#{#tbd1a} toExclusiveEndBoundary - inclusive dateTo → exclusive bulk-delete bound', () => {
270		// Transactions bulk-delete uses `< beforeDate`, so an inclusive dateTo must be
271		// advanced by one calendar day.
272		//
273		// The current inline code (transactions/+page.svelte:178-181,
274		// `new Date(dateTo + 'T12:00:00')` → `+1 day` → `toISOString()`) is correct for
275		// this app's realistic timezones (UTC−8..−3.5, and CI in UTC), but DRIFTS a day
276		// at extreme offsets — verified: it returns 2025-01-31 at UTC+14 and 2025-02-02
277		// at UTC−12 for the input below. These expectations therefore pin the *correct*
278		// calendar result; the extraction must build the boundary from Y/M/D string math
279		// (no `Date`/`toISOString`), not copy the current code verbatim.
280		it('advances a mid-month date by one day', () => {
281			expect(toExclusiveEndBoundary('2025-01-15')).toBe('2025-01-16');
282		});
283	
284		it('rolls over into the next month', () => {
285			expect(toExclusiveEndBoundary('2025-01-31')).toBe('2025-02-01');
286		});
287	
288		it('rolls over into the next year', () => {
289			expect(toExclusiveEndBoundary('2025-12-31')).toBe('2026-01-01');
290		});
291	
292		it('handles a leap-year February boundary', () => {
293			expect(toExclusiveEndBoundary('2024-02-28')).toBe('2024-02-29');
294			expect(toExclusiveEndBoundary('2024-02-29')).toBe('2024-03-01');
295		});
296	
297		it('handles a non-leap February boundary', () => {
298			expect(toExclusiveEndBoundary('2025-02-28')).toBe('2025-03-01');
299		});
300	});
