302	describe('#{#sdf2b} defaultMonthStart / defaultMonthEnd - reconciliation default range', () => {
303		// Reconciliation falls back to the current month when the URL carries no dates.
304		// Helpers take an explicit reference Date so the range is deterministic and
305		// timezone-safe (built from local Y/M/D, never `Date.toISOString()` on a
306		// local-midnight value, which would drift a day west of UTC).
307		it('returns the first day of the reference month', () => {
308			expect(defaultMonthStart(new Date(2025, 2, 15))).toBe('2025-03-01'); // March
309		});
310	
311		it('returns the last day of a 31-day reference month', () => {
312			expect(defaultMonthEnd(new Date(2025, 2, 15))).toBe('2025-03-31'); // March
313		});
314	
315		it('returns the last day of a 30-day reference month', () => {
316			expect(defaultMonthEnd(new Date(2025, 3, 10))).toBe('2025-04-30'); // April
317		});
318	
319		it('returns Feb 28 for a non-leap reference year', () => {
320			expect(defaultMonthEnd(new Date(2025, 1, 10))).toBe('2025-02-28');
321		});
322	
323		it('returns Feb 29 for a leap reference year', () => {
324			expect(defaultMonthEnd(new Date(2024, 1, 10))).toBe('2024-02-29');
325		});
326	
327		it('handles December (year does not roll over on the end date)', () => {
328			expect(defaultMonthStart(new Date(2025, 11, 20))).toBe('2025-12-01');
329			expect(defaultMonthEnd(new Date(2025, 11, 20))).toBe('2025-12-31');
330		});
