1	/**
2	 * Shared date-filter glue for the list pages (RF-02).
3	 *
4	 * The `expenses`, `receipts`, `transactions` and `reconciliation` pages all drive
5	 * an identical URL-backed date filter: read+validate `dateFrom`/`dateTo` from the
6	 * query string, filter an in-memory list against them, and build the query string
7	 * for the Apply/Clear actions. That glue used to be copy-pasted four times; this
8	 * module owns the pure logic and each page delegates to it. The reactive `$state`/
9	 * `$derived`/`$effect`/`goto` wiring stays on the pages (Svelte runes); only the
10	 * pure computation lives here so it is unit-testable in the node project.
11	 *
12	 * Behaviour is pinned by `sharedDateFilter.spec.ts`, whose expectations were
13	 * validated against the pre-extraction page code via an oracle harness. The two
14	 * date-math helpers (`toExclusiveEndBoundary`, `defaultMonth*`) are implemented
15	 * with Y/M/D string/UTC math rather than local `Date`+`toISOString`, which drifts
16	 * a day at extreme timezones (per CLAUDE.md's date-only-string rule).
17	 *
18	 * @module sharedDateFilter
19	 */
20	
21	import { getValidDate } from './dateValidation';
22	
23	export interface DateFilterValues {
24		dateFrom: string;
25		dateTo: string;
26	}
27	
28	const pad = (n: number): string => String(n).padStart(2, '0');
29	
30	/**
31	 * Read and validate the `dateFrom`/`dateTo` query parameters. Missing or invalid
32	 * values (wrong format, impossible dates, injection payloads) become `''`.
33	 */
34	export function readDateFilter(searchParams: URLSearchParams): DateFilterValues {
35		return {
36			dateFrom: getValidDate(searchParams.get('dateFrom')),
37			dateTo: getValidDate(searchParams.get('dateTo'))
38		};
39	}
40	
41	/**
42	 * Client-side in-memory predicate: does a row's date fall within the range?
43	 *
44	 * Rows with no date (`null`/`undefined`/`''`) are always kept — matching the
45	 * nullable-date pages (expenses/receipts/reconciliation); transactions has a
46	 * non-null date column, so the same predicate is equivalent for it. Bounds are
47	 * inclusive and compared as `YYYY-MM-DD` strings (never `new Date`).
48	 */
49	export function matchesDateRange(
50		date: string | null | undefined,
51		dateFrom: string,
52		dateTo: string
53	): boolean {
54		if (!date) return true;
55		if (dateFrom && date < dateFrom) return false;
56		if (dateTo && date > dateTo) return false;
57		return true;
58	}
59	
60	/**
61	 * Build the query params for "Apply": set each bound when truthy, delete it when
62	 * empty, and preserve all other params. Returns a new `URLSearchParams`; the input
63	 * is not mutated.
64	 */
65	export function applyDateFilterParams(
66		current: URLSearchParams,
67		dateFrom: string,
68		dateTo: string
69	): URLSearchParams {
70		const params = new URLSearchParams(current);
71		if (dateFrom) params.set('dateFrom', dateFrom);
72		else params.delete('dateFrom');
73		if (dateTo) params.set('dateTo', dateTo);
74		else params.delete('dateTo');
75		return params;
76	}
77	
78	/**
79	 * Build the query params for "Clear": drop both date bounds, preserve everything
80	 * else. Returns a new `URLSearchParams`; the input is not mutated.
81	 */
82	export function clearDateFilterParams(current: URLSearchParams): URLSearchParams {
83		const params = new URLSearchParams(current);
84		params.delete('dateFrom');
85		params.delete('dateTo');
86		return params;
87	}
88	
89	/**
90	 * Convert an inclusive `dateTo` into the exclusive end boundary a `< beforeDate`
91	 * query needs: the next calendar day. Uses UTC arithmetic so the result never
92	 * drifts by a day regardless of the runtime timezone.
93	 *
94	 * @example toExclusiveEndBoundary('2025-01-31') // '2025-02-01'
95	 */
96	export function toExclusiveEndBoundary(dateTo: string): string {
97		const [year, month, day] = dateTo.split('-').map(Number);
98		const next = new Date(Date.UTC(year, month - 1, day + 1));
99		return `${next.getUTCFullYear()}-${pad(next.getUTCMonth() + 1)}-${pad(next.getUTCDate())}`;
100	}
101	
102	/**
103	 * First day of the reference date's month, as `YYYY-MM-DD`. Used by reconciliation
104	 * as the default range start when the URL carries no dates. Built from the local
105	 * calendar parts, so it is timezone-stable.
106	 */
107	export function defaultMonthStart(ref: Date): string {
108		return `${ref.getFullYear()}-${pad(ref.getMonth() + 1)}-01`;
109	}
110	
111	/**
112	 * Last day of the reference date's month, as `YYYY-MM-DD`. Used by reconciliation
113	 * as the default range end when the URL carries no dates. Timezone-stable.
114	 */
115	export function defaultMonthEnd(ref: Date): string {
116		const year = ref.getFullYear();
117		const month = ref.getMonth();
118		const lastDay = new Date(year, month + 1, 0).getDate();
119		return `${year}-${pad(month + 1)}-${pad(lastDay)}`;
120	}
