3	/**
4	 * Shape of the minimal existing-row data needed for dedup:
5	 * only the fields that participate in the match key.
6	 */
7	export interface ExistingTransactionRow {
8		transaction_date: string;
9		vendor_name: string;
10		amount: number;
11	}
12	
13	export interface ImportPlan {
14		toInsert: ParsedTransaction[];
15		skipped: number;
16	}
17	
18	/**
19	 * Count-based duplicate detection for transaction imports.
20	 *
21	 * Specifications implemented:
22	 * - #{#tid1a} Count-based duplicate detection
23	 * - #{#tid2a} Dedup algorithm
24	 *
25	 * For each distinct match key `(transaction_date, vendor_name, amount)` in `fileRows`,
26	 * inserts `max(0, fileCount - dbCount)` rows. Rows beyond that threshold are counted
27	 * as skipped. Caller is responsible for scoping `existingRows` to the same
28	 * `(family_id, credit_card_type)` as the import (see #{#tid2b}) and for including
29	 * excluded rows so re-import doesn't resurrect them (see #{#tid5a}).
30	 */
31	export function computeImportPlan(
32		fileRows: ParsedTransaction[],
33		existingRows: ExistingTransactionRow[]
34	): ImportPlan {
35		const keyOf = (r: { transaction_date: string; vendor_name: string; amount: number }) =>
36			`${r.transaction_date}|${r.vendor_name}|${r.amount}`;
37	
38		const dbCounts = new Map<string, number>();
39		for (const r of existingRows) {
40			const k = keyOf(r);
41			dbCounts.set(k, (dbCounts.get(k) ?? 0) + 1);
42		}
43	
44		const fileGroups = new Map<string, ParsedTransaction[]>();
45		for (const t of fileRows) {
46			const k = keyOf(t);
47			const group = fileGroups.get(k) ?? [];
48			group.push(t);
49			fileGroups.set(k, group);
50		}
51	
52		const toInsert: ParsedTransaction[] = [];
53		let skipped = 0;
54		for (const [key, rows] of fileGroups) {
55			const dbCount = dbCounts.get(key) ?? 0;
56			const insertCount = Math.max(0, rows.length - dbCount);
57			toInsert.push(...rows.slice(0, insertCount));
58			skipped += rows.length - insertCount;
59		}
60	
61		return { toInsert, skipped };
62	}
