	async importFromCSV(
		familyId: string,
		file: File,
		creditCardType: CreditCardType
	): Promise<{
		imported: number;
		skipped: number;
		errors: string[];
	}> {
		const parseResult = await this.parseCSV(file, creditCardType);

		if (parseResult.transactions.length === 0) {
			return { imported: 0, skipped: 0, errors: parseResult.errors };
		}

		const errors: string[] = [...parseResult.errors];

		// #{#tid2a}: single scoped query for existing rows in the file's date range.
		// #{#tid2b}: scope to (family_id, credit_card_type).
		// #{#tid5a}: no excluded filter — excluded rows count toward dbCount.
		const dates = parseResult.transactions.map((t) => t.transaction_date);
		const minDate = dates.reduce((a, b) => (a < b ? a : b));
		const maxDate = dates.reduce((a, b) => (a > b ? a : b));

		const { data: existingRows, error: selectError } = await this.supabase
			.from('transactions')
			.select('transaction_date, vendor_name, amount')
			.eq('family_id', familyId)
			.eq('credit_card_type', creditCardType)
			.gte('transaction_date', minDate)
			.lte('transaction_date', maxDate);

		if (selectError) {
			throw new Error(`Failed to load existing transactions: ${selectError.message}`);
		}

		const plan = computeImportPlan(
			parseResult.transactions,
			(existingRows ?? []) as ExistingTransactionRow[]
		);

		if (plan.toInsert.length === 0) {
			return { imported: 0, skipped: plan.skipped, errors };
		}

		const rowsToInsert = plan.toInsert.map((t) => ({
			family_id: familyId,
			transaction_date: t.transaction_date,
			vendor_name: t.vendor_name,
			amount: t.amount,
			credit_card_type: creditCardType
		}));

		const { error: insertError } = await this.supabase.from('transactions').insert(rowsToInsert);

		if (insertError) {
			errors.push(`Failed to insert transactions: ${insertError.message}`);
			return { imported: 0, skipped: plan.skipped, errors };
		}

		return { imported: plan.toInsert.length, skipped: plan.skipped, errors };
	}

